PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, phone TEXT, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('renter','staff','owner','admin')), verified INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_recovery (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, channel TEXT NOT NULL CHECK(channel IN ('email','sms')), otp_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, sent_at INTEGER NOT NULL, window_started_at INTEGER NOT NULL, request_count INTEGER NOT NULL DEFAULT 1, verified_at INTEGER, reset_token_hash TEXT, reset_expires_at INTEGER, delivery_id TEXT);
CREATE TABLE IF NOT EXISTS staff_profiles (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, verification_status TEXT NOT NULL DEFAULT 'pending', verification_details TEXT);
CREATE TABLE IF NOT EXISTS owner_profiles (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, address TEXT NOT NULL, verification_status TEXT NOT NULL DEFAULT 'pending' CHECK(verification_status IN ('pending','approved','rejected')), verification_reason TEXT, id_document BLOB NOT NULL, id_document_mime TEXT NOT NULL, profile_picture BLOB, profile_picture_mime TEXT);
CREATE TABLE IF NOT EXISTS vehicles (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, brand TEXT NOT NULL, model TEXT NOT NULL, type TEXT NOT NULL, location TEXT NOT NULL, price_per_day INTEGER NOT NULL CHECK(price_per_day>0), seats INTEGER NOT NULL, transmission TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image_url TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','rejected','maintenance')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, year INTEGER, plate_number TEXT, fuel_type TEXT NOT NULL DEFAULT 'Gasoline', color TEXT, requirements TEXT NOT NULL DEFAULT '', availability_schedule TEXT NOT NULL DEFAULT '', is_enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS vehicle_images (id INTEGER PRIMARY KEY, vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE, image_url TEXT NOT NULL, storage_path TEXT, original_name TEXT NOT NULL DEFAULT '', mime_type TEXT NOT NULL DEFAULT '', file_size INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, is_primary INTEGER NOT NULL DEFAULT 0, moderation_status TEXT NOT NULL DEFAULT 'pending' CHECK(moderation_status IN ('pending','approved','rejected')), uploaded_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, photo_type TEXT NOT NULL DEFAULT 'general');
CREATE TABLE IF NOT EXISTS bookings (id INTEGER PRIMARY KEY, reference TEXT NOT NULL UNIQUE, renter_id INTEGER NOT NULL REFERENCES users(id), vehicle_id INTEGER NOT NULL REFERENCES vehicles(id), pickup_date TEXT NOT NULL, return_date TEXT NOT NULL, days INTEGER NOT NULL, subtotal INTEGER NOT NULL, service_fee INTEGER NOT NULL, total INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'payment_pending' CHECK(status IN ('payment_pending','pending','confirmed','rejected','active','completed','cancelled')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, rejection_reason TEXT, handover_condition TEXT, return_condition TEXT, damage_report TEXT, handover_photo_url TEXT, return_photo_url TEXT, CHECK(return_date>pickup_date));
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY, booking_id INTEGER NOT NULL UNIQUE REFERENCES bookings(id), provider TEXT NOT NULL DEFAULT 'GCash' CHECK(provider='GCash'), amount INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','successful','failed','refunded')), provider_reference TEXT, proof_url TEXT, verified_by INTEGER REFERENCES users(id), verified_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions (id INTEGER PRIMARY KEY, payment_id INTEGER NOT NULL REFERENCES payments(id), kind TEXT NOT NULL, amount INTEGER NOT NULL, note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY, booking_id INTEGER NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, sender_id INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY, booking_id INTEGER NOT NULL UNIQUE REFERENCES bookings(id), renter_id INTEGER NOT NULL REFERENCES users(id), vehicle_id INTEGER NOT NULL REFERENCES vehicles(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), comment TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vehicle_availability (id INTEGER PRIMARY KEY, vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE, unavailable_from TEXT NOT NULL, unavailable_to TEXT NOT NULL, reason TEXT NOT NULL DEFAULT 'maintenance');
CREATE TABLE IF NOT EXISTS maintenance_records (id INTEGER PRIMARY KEY, vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE, owner_id INTEGER NOT NULL REFERENCES users(id), description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, maintenance_date TEXT, scheduled_date TEXT, receipt_url TEXT);
CREATE TABLE IF NOT EXISTS activity_logs (id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity TEXT, entity_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS booking_vehicle_dates ON bookings(vehicle_id,pickup_date,return_date,status);
CREATE INDEX IF NOT EXISTS notifications_user_read ON notifications(user_id,read_at);
